const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
// Safe no-op placeholders so inline onclick handlers won't throw if clicked before full init
window.openChat = window.openChat || function(){};
window.openGroup = window.openGroup || function(){};
window.pickDay = window.pickDay || function(){};
function closeModal(){
  document.querySelector('#modalWrap')?.remove();
}
window.closeModal = closeModal;
let token=localStorage.getItem('campus_token'), me=null, socket=null, currentPage='home', activeChat=null, selectedDay='Monday', cache={};
const api=async(path,opt={})=>{opt.headers={...(opt.headers||{}),'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})};let r;try{r=await fetch(path,opt);}catch(err){console.error('Network error calling api',path,err);throw Error('Network error');}if(r.status===401){localStorage.removeItem('campus_token');token=null;if(socket){try{socket.disconnect()}catch(err){console.warn('Socket disconnect failed',err)}}showAuth();throw Error('Unauthorized');}const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'Something went wrong');return d};
const toast=(msg,type='')=>{const d=document.createElement('div');d.className='toast '+type;d.textContent=msg;$('#toast').appendChild(d);setTimeout(()=>d.remove(),3200)};
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const initials=n=>String(n||'U').split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();
const fmt=t=>t?new Date(t).toLocaleString([], {day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'';

// Click delegation: prefer data-action / data-id / data-args attributes; fall back to inline onclick parsing.
document.addEventListener('click', e => {
  const el = e.target instanceof Element ? e.target.closest('[data-action],[onclick]') : null;
  if (!el) return;

  // Handle data-action first
  const action = el.dataset.action;
  if (action) {
    const fn = window[action];
    if (typeof fn === 'function') {
      let args = [];
      if (el.dataset.id !== undefined && el.dataset.id !== '') {
        const id = el.dataset.id;
        args.push(/^\d+$/.test(id) ? Number(id) : id);
      }
      if (el.dataset.args) {
        try { const parsed = JSON.parse(el.dataset.args); if (Array.isArray(parsed)) args = args.concat(parsed); else args.push(parsed); } catch(err){ console.warn('Invalid data-args', el.dataset.args, err); }
      }
      // pass the element as last arg for handlers that want it
      args.push(el);
      e.preventDefault();
      try {
        Promise.resolve(fn.apply(null, args)).catch(err => {
          console.error('delegated data-action call failed', action, args, err);
          toast(err.message || 'Action failed', 'err');
        });
      } catch(err){ console.error('delegated data-action call failed', action, args, err); }
      return;
    } else {
      console.warn('data-action function not found', action);
    }
  }

  // Fallback: parse inline onclick attribute
  const code = el.getAttribute('onclick')?.trim();
  if (!code) return;
  const m = code.match(/^([a-zA-Z0-9_$]+)\s*\((.*)\)\s*;?$/);
  if (m){
    const name = m[1];
    const argsStr = m[2].trim();
    const fn = window[name];
    if (typeof fn === 'function') {
      let args = [];
      if (argsStr.length) {
        try { args = new Function('return ['+argsStr+']')(); } catch(err){ console.warn('Could not parse onclick args', argsStr, err); }
      }
      args.push(el);
      e.preventDefault();
      try {
        Promise.resolve(fn.apply(null, args)).catch(err => {
          console.error('delegated call failed', name, args, err);
          toast(err.message || 'Action failed', 'err');
        });
      } catch(err){ console.error('delegated call failed', name, args, err); }
      return;
    }
  }
});

// Polling fallback for realtime features when socket.io client is unavailable.
let __chat_poll_interval = null;
function ensurePolling(){
  if (typeof io === 'function') { if(__chat_poll_interval){ clearInterval(__chat_poll_interval); __chat_poll_interval=null; } return; }
  if(__chat_poll_interval) return;
  __chat_poll_interval = setInterval(()=>{
    try{
      if(currentPage==='chat') loadChats(false);
      loadBadges();
    }catch(e){/* ignore */}
  }, 10000);
}

function showAuth(){ $('#authView').classList.remove('hidden'); $('#appView').classList.add('hidden'); }
function showApp(){
 $('#authView')?.classList.add('hidden'); $('#appView')?.classList.remove('hidden');
 applyRoleUI(); syncProfileUI(); try{ setupSocket(); }catch(e){console.error('setupSocket error',e)} ensurePolling();
 if(me?.role==='personal' && ['groups','timetable','attendance','events','admin'].includes(currentPage)) currentPage='home';
 renderPage(currentPage); loadBadges(); // ensure chat list is loaded so openChat/loadMessages can find cache
 try{ if(currentPage==='chat') loadChats(true); else loadChats(false); }catch(e){}
}
function applyRoleUI(){
 const personal=me?.role==='personal';
 $$('.collegeOnly').forEach(b=>b.classList.toggle('hidden',personal));
 $('.adminOnly')?.classList.toggle('hidden',me?.role!=='admin');
 $('#pageEyebrow').textContent=personal?'PERSONAL ACCOUNT':me?`${me.course||'CAMPus'} · ${me.role.toUpperCase()}`:'CAMPUS COMMUNITY';
}
function syncProfileUI(){
 if(!me)return;
 const name=me.name||'User';
 const initialsText=initials(name);
 if($('#avatar'))$('#avatar').textContent=initialsText;
 if($('#topAvatar'))$('#topAvatar').textContent=initialsText;
 if($('#sideName'))$('#sideName').textContent=name;
 if($('#topName'))$('#topName').textContent=name;
 if($('#sideRole'))$('#sideRole').textContent=me.role==='teacher'&&me.teacher_verified?'Verified teacher':String(me.role||'User');
}
const showAuthForm=form=>{$$('.auth-form').forEach(x=>x.classList.add('hidden'));if(form)$(form)?.classList.remove('hidden');};
$$('.tab').forEach(b=>b.onclick=()=>{ $$('.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');showAuthForm(b.dataset.auth==='register'?'#registerForm':'#loginForm'); });
const loginForm = $('#loginForm'); if(loginForm) loginForm.onsubmit=async e=>{e.preventDefault();try{const d=await api('/api/auth/login',{method:'POST',body:JSON.stringify({email:$('#loginEmail').value,password:$('#loginPassword').value})});token=d.token;localStorage.setItem('campus_token',token);me=d.user;showApp();toast('Welcome back, '+me.name.split(' ')[0]+'!','ok')}catch(err){toast(err.message,'err')}};
$('#forgotPasswordBtn')?.addEventListener('click',()=>showAuthForm('#forgotForm'));
$('#backToLoginBtn')?.addEventListener('click',()=>showAuthForm('#loginForm'));
$('#forgotForm')?.addEventListener('submit',async e=>{e.preventDefault();try{const d=await api('/api/auth/forgot-password',{method:'POST',body:JSON.stringify({email:$('#forgotEmail').value})});toast(d.message,'ok');showAuthForm('#loginForm')}catch(err){toast(err.message,'err')}});
$('#resetForm')?.addEventListener('submit',async e=>{e.preventDefault();if($('#resetPassword').value!==$('#resetPasswordConfirm').value)return toast('Passwords do not match','err');try{const d=await api('/api/auth/reset-password',{method:'POST',body:JSON.stringify({token:new URLSearchParams(location.search).get('reset_token'),password:$('#resetPassword').value})});history.replaceState({},'',location.pathname);toast(d.message,'ok');showAuthForm('#loginForm')}catch(err){toast(err.message,'err')}});
const regRole = $('#regRole'); const toggleTeacherFields=()=>{const role=regRole?.value;const personal=role==='personal';$('#regCourse')?.closest('label').style&&(($('#regCourse').closest('label').style.display=personal?'none':''));$('#regYear')?.closest('label').style&&(($('#regYear').closest('label').style.display=personal?'none':''));$('#teacherVerificationFields')?.classList.toggle('hidden',role!=='teacher')}; if(regRole){regRole.onchange=toggleTeacherFields;toggleTeacherFields()}
const registerForm = $('#registerForm'); if(registerForm) registerForm.onsubmit=async e=>{e.preventDefault();try{const d=await api('/api/auth/register',{method:'POST',body:JSON.stringify({name:$('#regName').value,email:$('#regEmail').value,password:$('#regPassword').value,role:$('#regRole').value,course:$('#regCourse').value,year:+$('#regYear').value,institution:$('#regInstitution')?.value,department:$('#regDepartment')?.value,employee_id:$('#regEmployeeId')?.value,qualification:$('#regQualification')?.value,teaching_subjects:$('#regSubjects')?.value,verification_document:$('#regProof')?.value})});token=d.token;localStorage.setItem('campus_token',token);me=d.user;showApp();toast(d.message,'ok')}catch(err){toast(err.message,'err')}};
$('#logoutBtn').onclick=async()=>{try{await api('/api/auth/logout',{method:'POST'})}catch{}localStorage.removeItem('campus_token');token=null;if(socket)socket.disconnect();showAuth()};

function setupSocket(){try{if(socket||!token)return; if(typeof io !== 'function'){console.warn('socket.io client (io) not available - realtime features disabled'); ensurePolling(); return;} socket=io({auth:{token},reconnection:true}); socket.on('connect',()=>{console.debug('socket connected'); if(__chat_poll_interval){ clearInterval(__chat_poll_interval); __chat_poll_interval=null; }}); socket.on('connect_error',err=>{console.warn('socket connect_error',err);ensurePolling()}); socket.on('message:new',m=>{loadBadges(); if(activeChat===m.sender_id||activeChat===m.receiver_id){ loadMessages(activeChat) }}); socket.on('typing',p=>{if(currentPage==='chat'&&activeChat===p.from){const indicator=$('#typingIndicator');if(indicator){indicator.textContent=p.typing?'Typing…':'';indicator.classList.toggle('hidden',!p.typing)}}}); socket.on('presence',p=>{ if(currentPage==='chat') loadChats(false) }); socket.on('notification:new',n=>{ toast(n.title); if(localStorage.getItem('campus_reminders_enabled')==='1'&&'Notification' in window&&Notification.permission==='granted')new Notification(n.title,{body:n.body||'Your class is starting soon.'}); loadBadges(); if(currentPage==='notifications') renderPage('notifications') }); }catch(err){console.error('setupSocket failed',err);ensurePolling();} }
function nav(page){currentPage=page;$$('.nav').forEach(x=>x.classList.toggle('active',x.dataset.page===page));renderPage(page);}
$('#nav').onclick=e=>{const b=e.target.closest('.nav');if(b)nav(b.dataset.page)};$$('[data-page]').forEach(b=>{if(!b.classList.contains('nav'))b.onclick=()=>nav(b.dataset.page)});
const titles={home:'Home',discover:'Discover',groups:'Groups',chat:'Messages',timetable:'Timetable',attendance:'Attendance',events:'Events',notifications:'Notifications',profile:'Profile',admin:'Admin Console'};
async function renderPage(page){if(me?.role==='personal'&&['groups','timetable','attendance','events','admin'].includes(page)){page='home';currentPage='home';}$('#pageTitle').textContent=titles[page]||'CAMPus';$('#pageEyebrow').textContent=me?`${me.course||'CAMPus'} · ${me.role.toUpperCase()}`:'CAMPUS COMMUNITY';if(!me)return;try{const fn={home:home,discover:discover,groups:groups,chat:chat,timetable:timetable,attendance:attendance,events:events,notifications:notifications,profile:profile,admin:admin}[page]||home;$('#content').innerHTML='<div class="empty">Loading CAMPus…</div>';await fn()}catch(e){$('#content').innerHTML=`<div class="card notice">${esc(e.message)}</div>`}}

async function home(){
 if(me.role==='personal'){
  const users=await api('/api/users');cache.users=users;
  $('#content').innerHTML=`<div class="card hero"><span class="badge" style="background:#ffffff1a;color:#fff">PERSONAL SPACE</span><h1>Just connect and chat.</h1><p>Your Personal account keeps CAMPus simple: discover people and have normal one-to-one conversations. College academic tools are not included.</p><button class="ghost" style="background:#ffffff18;color:#fff;border-color:#ffffff20" data-action="nav" data-args='["chat"]'>Open messages →</button></div><div class="section-head"><h3>People on CAMPus</h3><span>${users.length} people</span></div><div class="grid grid3">${users.slice(0,6).map(personCard).join('')}</div>`;
  return;
 }
 const [posts,groups,events,rem]=await Promise.all([api('/api/posts'),api('/api/groups'),api('/api/events'),api('/api/reminders')]);cache={...cache,posts,groups,events,rem};$('#content').innerHTML=`<div class="card hero"><span class="badge" style="background:#ffffff1a;color:#fff">WELCOME BACK</span><h1>Build your campus life in one place.</h1><p>Connect with classmates, keep up with college events, track attendance and never miss your next class.</p><button class="ghost" style="background:#ffffff18;color:#fff;border-color:#ffffff20" data-action="nav" data-args='["groups"]'>Explore your groups →</button></div><div class="grid grid3" style="margin-top:18px"><div class="card stat"><div><small>Groups</small><strong>${groups.length}</strong></div><span class="badge">Community</span></div><div class="card stat"><div><small>Upcoming events</small><strong>${events.length}</strong></div><span class="badge orange">Events</span></div><div class="card stat"><div><small>Today's classes</small><strong>${rem.reminders.length}</strong></div><span class="badge green">Smart</span></div></div><div class="section-head"><h3>Share something with campus</h3><span>Public feed</span></div><div class="card composer"><div class="avatar">${initials(me.name)}</div><div class="composer-fields"><textarea id="postText" placeholder="What’s happening on campus?"></textarea><div class="composer-tools"><label class="photo-picker">📷 Add photo<input id="postImage" type="file" accept="image/jpeg,image/png,image/gif,image/webp"></label><span id="photoName" class="muted small"></span><button class="primary" data-action="createPost">Post</button></div><img id="postPreview" class="post-preview hidden" alt="Selected photo preview"></div></div><div class="section-head"><h3>Campus feed</h3><span>${posts.length} posts</span></div><div class="grid">${posts.map(postCard).join('')}</div>`
 const imageInput=$('#postImage');if(imageInput)imageInput.onchange=()=>{const file=imageInput.files?.[0];if(!file)return;$('#photoName').textContent=file.name;const preview=$('#postPreview');preview.src=URL.createObjectURL(file);preview.classList.remove('hidden')};
}
function avatarMarkup(u,small=''){return u?.avatar_data?`<img class="avatar ${small}" src="${esc(u.avatar_data)}" alt="${esc(u.name||'User')}">`:`<div class="avatar ${small}">${initials(u?.name)}</div>`}
function postCard(p){return `<div class="card post"><div class="post-head">${avatarMarkup(p)}<div style="flex:1"><b>${esc(p.name)} ${p.role==='teacher'?'<span class="badge green">Teacher</span>':''}</b><small>${esc(p.course)} · Year ${p.year} · ${fmt(p.created_at)}</small></div>${p.user_id!==me.id?'<button class="ghost" data-action="reportPost" data-id="'+p.id+'">Report</button>':''}</div>${p.text?`<div class="post-body">${esc(p.text).replace(/\n/g,'<br>')}</div>`:''}${p.image_data?`<img class="post-image" src="${esc(p.image_data)}" alt="Shared by ${esc(p.name)}" loading="lazy">`:''}<div class="post-actions"><button class="ghost ${p.liked?'liked':''}" data-action="likePost" data-id="${p.id}">♥ ${p.likes}</button><button class="ghost" data-action="openComments" data-id="${p.id}">💬 Comment</button><button class="ghost" data-action="sharePost" data-id="${p.id}">↗ Share</button></div></div>`}
window.reportPost=async id=>{modal(`<div class="modal-head"><h3>Report post</h3><button class="ghost" data-action="closeModal">Cancel</button></div><form id="reportForm"><label>Why are you reporting this post?<textarea id="reportReason" required minlength="3" maxlength="500" placeholder="Describe the issue...">Inappropriate content</textarea></label><button class="primary full" type="submit">Send report</button></form>`);$('#reportForm').onsubmit=async e=>{e.preventDefault();try{const reason=$('#reportReason').value.trim();if(!reason)return;await api('/api/posts/'+id+'/report',{method:'POST',body:JSON.stringify({reason})});closeModal();toast('Report sent to Admin','ok')}catch(err){toast(err.message,'err')}}};
window.createPost=async()=>{try{const file=$('#postImage')?.files?.[0];if(file&&(file.size>3*1024*1024||!/^image\/(jpeg|png|gif|webp)$/.test(file.type)))throw Error('Choose a JPG, PNG, GIF or WebP image smaller than 3 MB');let image_data='';if(file)image_data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Could not read the selected photo'));reader.readAsDataURL(file)});await api('/api/posts',{method:'POST',body:JSON.stringify({text:$('#postText').value,image_data})});toast('Post published','ok');home()}catch(e){toast(e.message,'err')}};
window.likePost=async(id,b)=>{try{const d=await api('/api/posts/'+id+'/like',{method:'POST'});b.classList.toggle('liked',d.liked);b.innerHTML='♥ '+d.likes}catch(e){toast(e.message,'err')}};
window.openComments=async id=>{try{const cs=await api('/api/posts/'+id+'/comments');modal(`<div class="modal-head"><h3>Comments</h3><button class="close" data-action="closeModal">×</button></div><div class="list">${cs.length?cs.map(c=>`<div class="list-item"><div class="avatar">${initials(c.name)}</div><div><b>${esc(c.name)}</b><small>${fmt(c.created_at)}</small><div style="margin-top:4px">${esc(c.text)}</div></div></div>`).join(''):'<div class="empty">No comments yet.</div>'}</div><form id="commentForm" style="margin-top:15px"><label>Add comment<textarea id="commentText" required></textarea></label><button class="primary full">Comment</button></form>`);$('#commentForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/posts/'+id+'/comments',{method:'POST',body:JSON.stringify({text:$('#commentText').value})});openComments(id)}catch(err){toast(err.message,'err')}}}catch(e){toast(e.message,'err')}};
window.sharePost=async id=>{const link=location.origin+'/#post-'+id;try{await navigator.clipboard.writeText(link);toast('Post link copied','ok')}catch{toast(link)}};
function ownPostCard(p){return `<div class="card post"><div class="post-head"><div class="avatar">${initials(p.name)}</div><div style="flex:1"><b>${esc(p.name)}</b><small>${esc(p.course)} · Year ${p.year} · ${fmt(p.created_at)}</small></div><button class="ghost danger-action" data-action="deletePost" data-id="${p.id}">Delete</button></div>${p.text?`<div class="post-body">${esc(p.text).replace(/\n/g,'<br>')}</div>`:''}${p.image_data?`<img class="post-image" src="${esc(p.image_data)}" alt="Shared by ${esc(p.name)}" loading="lazy">`:''}<div class="post-actions"><span class="muted small">♥ ${p.likes} likes</span><button class="ghost" data-action="openComments" data-id="${p.id}">💬 Comments</button></div></div>`}
window.deletePost=async id=>{if(!confirm('Delete this post permanently?'))return;try{await api('/api/posts/'+id,{method:'DELETE'});toast('Post deleted','ok');profile()}catch(e){toast(e.message,'err')}};
// Copy code helper used by delegated buttons
window.copyCode = async code => { try { await navigator.clipboard?.writeText(code); toast('Code copied','ok'); } catch(e){ console.warn('copy failed', e); toast(code); } };

async function discover(){const users=await api('/api/users');cache.users=users;renderDiscover(users)}
function renderDiscover(users){const connected=users.filter(u=>u.connected),available=users.filter(u=>!u.connected);$('#content').innerHTML=`<div class="card discover-toolbar"><div class="search-row"><input id="userSearch" class="search" placeholder="Search students and teachers…" oninput="filterPeople()"><span class="badge">${users.length} people</span></div></div><div class="section-head"><h3>My connections</h3><span>${connected.length} connected</span></div><div id="connectedPeople" class="grid grid3">${connected.length?connected.map(personCard).join(''):'<div class="empty">No connections yet. Connect with someone to keep them here.</div>'}</div><div class="section-head"><h3>Discover people</h3><span>${available.length} available</span></div><div id="people" class="grid grid3">${available.map(personCard).join('')||'<div class="empty">No people found.</div>'}</div>`}
function personCard(u){const action=u.connected?'<span class="badge green">Connected</span>':u.request_sent?'<span class="badge">Request sent</span>':u.request_received?'<span class="badge">Respond in Notifications</span>':`<button class="ghost" data-action="connectUser" data-id="${u.id}">＋ Connect</button>`;return `<div class="card discover-person-card"><div class="post-head discover-person-head">${avatarMarkup(u,'sm')}<div class="discover-person-identity"><b>${esc(u.name)}</b><small class="discover-person-meta"><span class="dot ${u.online?'on':''}"></span><span>${esc(u.role)} · ${esc(String(u.course||'').toUpperCase())}${u.year?' · Year '+u.year:''}</span></small></div></div><p class="muted discover-person-bio">${esc(u.bio||'No bio yet.')}</p><div class="discover-person-actions">${action}${u.connected?'<button class="primary" data-action="openChat" data-id="'+u.id+'">Message</button>':''}<button class="ghost danger-action" data-action="blockUser" data-id="${u.id}">Block</button></div></div>`}
window.filterPeople=()=>{const q=($('#userSearch')?.value||'').toLowerCase();const filtered=cache.users.filter(u=>(u.name+u.course+u.role).toLowerCase().includes(q));const connected=filtered.filter(u=>u.connected),available=filtered.filter(u=>!u.connected);if($('#connectedPeople'))$('#connectedPeople').innerHTML=connected.length?connected.map(personCard).join(''):'<div class="empty">No matching connections.</div>';if($('#people'))$('#people').innerHTML=available.length?available.map(personCard).join(''):'<div class="empty">No people found.</div>'};
window.connectUser=async id=>{try{await api('/api/users/'+id+'/connect',{method:'POST'});const user=cache.users.find(u=>u.id===Number(id));if(user){user.request_sent=true;user.connected=false}toast('Connection request sent','ok');renderDiscover(cache.users)}catch(e){toast(e.message,'err')}};
window.blockUser=async id=>{if(!confirm('Block this user? They will disappear from Discover and messaging will be disabled.'))return;try{await api('/api/users/'+id+'/block',{method:'POST'});cache.users=cache.users.filter(u=>u.id!==Number(id));toast('User blocked','ok');renderDiscover(cache.users)}catch(e){toast(e.message,'err')}};
window.unblockUser=async id=>{try{await api('/api/users/'+id+'/block',{method:'DELETE'});toast('User unblocked','ok');profile()}catch(e){toast(e.message,'err')}};

async function groups(){const gs=await api('/api/groups');cache.groups=gs;$('#content').innerHTML=`<div class="grid grid2"><div class="card hero"><span class="badge" style="background:#ffffff1a;color:#fff">COLLEGE GROUPS</span><h1>Find your people.</h1><p>Join course/year communities with a simple group code or one tap.</p><div style="display:flex;gap:8px;margin-top:18px"><button class="ghost" style="background:#fff;color:#4f39d1" data-action="joinGroupCode">Join with code</button>${['teacher','admin'].includes(me.role)&&(!me.role==='teacher'||me.teacher_verified)?'':''}${me.role==='admin'||(me.role==='teacher'&&me.teacher_verified)?'<button class="ghost" style="background:#ffffff18;color:#fff;border-color:#ffffff22" data-action="openCreateGroup">＋ Create group</button>':''}</div></div><div class="card"><h3 style="margin-top:0">Your group shortcut</h3><p class="muted">Use the code shared by your teacher/admin.</p><div class="search-row"><input id="groupCode" placeholder="e.g. BCA3RD26"><button class="primary" data-action="joinGroupCode">Join</button></div></div></div><div class="section-head"><h3>All groups</h3><span>${gs.length} communities</span></div><div class="grid grid3">${gs.map(g=>`<div class="card group-card"><div><span class="badge">${esc(g.course)} · Year ${g.year}</span><h3>${esc(g.name)}</h3><p class="muted">${esc(g.description)}</p></div><div class="bottom"><div><b>${g.members}</b> <small class="muted">members</small><br><span class="code">${esc(g.code)}</span></div>${g.joined?`<div style="display:flex;gap:7px"><span class="badge green">Joined</span><button class="ghost" data-action="openGroup" data-id="${g.id}">Open</button></div>`:`<button class="primary" data-action="joinGroup" data-id="${g.id}">Join group</button>`}</div></div>`).join('')}</div>`}
window.joinGroup=async id=>{try{await api('/api/groups/'+id+'/join',{method:'POST'});toast('Joined group','ok');groups()}catch(e){toast(e.message,'err')}};window.joinGroupCode=async()=>{const code=$('#groupCode')?.value?.trim()||prompt('Enter group code');if(!code)return;try{await api('/api/groups/join',{method:'POST',body:JSON.stringify({code})});toast('Joined group','ok');groups()}catch(e){toast(e.message,'err')}};
window.openCreateGroup=()=>{modal(`<div class="modal-head"><h3>Create college group</h3><button class="close" data-action="closeModal">×</button></div><form id="groupForm"><label>Group name<input id="gName" required placeholder="BCA 3rd Year"></label><label>Description<textarea id="gDesc" placeholder="What is this group for?"></textarea></label><div class="two"><label>Course<input id="gCourse" value="BCA"></label><label>Year<input id="gYear" type="number" min="1" value="3"></label></div><label>Custom code (optional)<input id="gCode" placeholder="BCA3RD26"></label><button class="primary full">Create group</button></form>`);const form=$('#groupForm');if(form)form.onsubmit=async e=>{e.preventDefault();try{const g=await api('/api/groups',{method:'POST',body:JSON.stringify({name:$('#gName').value,description:$('#gDesc').value,course:$('#gCourse').value,year:+$('#gYear').value,code:$('#gCode').value||undefined})});closeModal();toast('Group created · '+g.code,'ok');groups()}catch(e){toast(e.message,'err')}}};

async function chat(){const chats=await api('/api/chats');cache.chats=chats;$('#content').innerHTML=`<div class="card chat-layout"><div class="chat-list"><input class="chat-search" id="chatSearch" placeholder="Search people…" oninput="filterChats()"><div id="chatPeople">${chats.map(chatItem).join('')}</div></div><div class="chat-window" id="chatWindow">${activeChat?'<div class="empty">Loading conversation…</div>':'<div class="empty"><div style="font-size:35px">💬</div><h3>Pick a conversation</h3><p>Send a normal one-to-one message in real time.</p></div>'}</div></div>`;if(activeChat)loadMessages(activeChat)}
function chatItem(u){return `<div class="chat-user ${activeChat===u.id?'active':''}" data-action="openChat" data-id="${u.id}"><div class="avatar">${initials(u.name)}</div><div class="grow"><b>${esc(u.name)}</b><small><span class="dot ${u.online?'on':''}"></span>${esc(u.role)}</small><div class="last">${esc(u.last_message||'Start a conversation')}</div></div>${u.unread?`<span class="unread">${u.unread}</span>`:''}</div>`}
window.filterChats=()=>{const q=$('#chatSearch').value.toLowerCase();$('#chatPeople').innerHTML=cache.chats.filter(u=>u.name.toLowerCase().includes(q)).map(chatItem).join('')};window.openChat = id => { console.debug('openChat called with id:', id); activeChat = id; nav('chat'); };
async function loadChats(refresh=true){if(currentPage!=='chat')return;const chats=await api('/api/chats');cache.chats=chats;if($('#chatPeople'))$('#chatPeople').innerHTML=chats.map(chatItem).join('');if(activeChat)loadMessages(activeChat)}
async function loadMessages(id){ console.debug('loadMessages called with id:', id); try{ const msgs = await api('/api/chats/'+id+'/messages'); loadBadges(); const u = cache.chats?.find(x=>x.id===id) || {name:'Conversation',online:false}; const w = $('#chatWindow'); if(!w){ console.warn('chatWindow element not found'); return; } w.innerHTML =  `<div class="chat-head"><div class="avatar">${initials(u.name)}</div><div><b>${esc(u.name)}</b><small style="display:block;color:var(--muted)"><span class="dot ${u.online?'on':''}"></span>${u.online?'Online':'Offline'}</small></div></div><div class="chat-messages" id="messages">${msgs.map(m=>`<div class="bubble ${m.sender_id===me.id?'mine':''}">${esc(m.text)}<small>${fmt(m.created_at)} ${m.sender_id===me.id?(m.seen?'· Seen':'· Sent'):''}</small></div>`).join('')||'<div class="empty">No messages yet. Say hello 👋</div>'}</div><div id="typingIndicator" class="muted small hidden" aria-live="polite"></div><form class="chat-compose" id="messageForm"><input id="messageText" placeholder="Write a message…" autocomplete="off"><button class="primary">Send</button></form>`; const messageForm = $('#messageForm'); const messageInput=$('#messageText'); let typingTimer; if(messageInput) messageInput.oninput=()=>{if(socket?.connected)socket.emit('typing',{to:id,typing:true});clearTimeout(typingTimer);typingTimer=setTimeout(()=>{if(socket?.connected)socket.emit('typing',{to:id,typing:false})},900)}; if(messageForm) messageForm.onsubmit = async e => { e.preventDefault(); console.debug('messageForm submit for chat', id); const text = $('#messageText').value.trim(); if(!text) return; try{ if(socket?.connected)socket.emit('typing',{to:id,typing:false}); await api('/api/chats/'+id+'/messages',{method:'POST',body:JSON.stringify({text})}); $('#messageText').value=''; loadMessages(id); loadChats(false); }catch(err){ console.error('sending message failed', err); toast(err.message,'err'); } }; const box = $('#messages'); if(box) box.scrollTop = box.scrollHeight; }catch(err){ console.error('loadMessages error', err); toast(err.message||String(err),'err'); }}

function nextReminder(reminders){
 const nowMinutes=new Date().getHours()*60+new Date().getMinutes();
 const mapped=reminders.map(r=>{
   const [startHour,startMinute]=String(r.start).split(':').map(Number);
   const [endHour,endMinute]=String(r.end||r.start).split(':').map(Number);
   return {...r,startMinutes:startHour*60+startMinute,endMinutes:endHour*60+endMinute};
 });
 return mapped.find(r=>nowMinutes>=r.startMinutes&&nowMinutes<r.endMinutes)
   || mapped.find(r=>r.startMinutes>=nowMinutes);
}
window.enableReminders=async()=>{
 if(!('Notification' in window)){toast('Browser notifications are not supported','err');return}
 const permission=await Notification.requestPermission();
 if(permission==='granted'){localStorage.setItem('campus_reminders_enabled','1');toast('Smart reminders enabled','ok');timetable()}
 else toast('Please allow notifications in your browser','err');
};
async function timetable(){const rows=await api('/api/timetable');const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];const dayRows=rows.filter(x=>x.day===selectedDay);const rem=await api('/api/reminders');const next=nextReminder(rem.reminders||[]);const enabled=localStorage.getItem('campus_reminders_enabled')==='1';const canEdit=me.role==='admin'||(me.role==='teacher'&&me.teacher_verified);$('#content').innerHTML=`<div class="grid grid2"><div class="card"><div class="section-head" style="margin-top:0"><h3>${selectedDay} schedule</h3><span>${dayRows.length} classes</span></div><div class="day-tabs">${days.map(d=>`<button class="day-tab ${selectedDay===d?'active':''}" data-action="pickDay" data-args='["${d}"]'>${d.slice(0,3)}</button>`).join('')}</div>${dayRows.length?dayRows.map(s=>`<div class="slot ${next&&next.subject===s.subject&&next.start===s.start?'next-class':''}"><div class="time">${s.start_time}<small>${s.end_time}</small></div><div><b>${esc(s.subject)}</b><small class="muted" style="display:block;margin-top:4px">${esc(s.teacher||'Faculty')} · ${esc(s.room||'Room TBA')}</small></div><span class="badge">${esc(s.course)} ${s.year}</span>${canEdit?`<div class="slot-actions"><button class="ghost" data-action="editSlot" data-id="${s.id}">Edit</button><button class="ghost danger-action" data-action="deleteSlot" data-id="${s.id}">Delete</button></div>`:''}</div>`).join(''):'<div class="empty">No class scheduled for this day.</div>'}</div><div class="grid"><div class="card reminder-card"><span class="badge">SMART REMINDER</span><h3>Never miss your next class</h3>${next?`<div class="notice reminder-next">⏰ <b>${esc(next.subject)}</b><strong>${esc(next.start)} · ${esc(next.room||'Room TBA')}</strong><small>${esc(next.message)}</small></div>`:'<p class="muted">No more classes scheduled today. You’re all clear.</p>'}<button class="ghost reminder-toggle" data-action="enableReminders">${enabled?'✓ Browser reminders enabled':'Enable browser reminders'}</button><small class="muted">You’ll get a notification when a class is starting soon.</small></div>${teacherControls('timetable')}</div></div>`}
window.pickDay=d=>{selectedDay=d;timetable()};
window.deleteSlot=async id=>{if(!confirm('Delete this timetable slot?'))return;try{await api('/api/timetable/'+id,{method:'DELETE'});toast('Timetable slot deleted','ok');timetable()}catch(e){toast(e.message,'err')}};
window.editSlot=async id=>{const rows=await api('/api/timetable');const s=rows.find(x=>x.id===Number(id));if(!s)return;modal(`<div class="modal-head"><h3>Edit timetable slot</h3><button class="close" data-action="closeModal">×</button></div><form id="editSlotForm"><div class="two"><label>Course<input id="sCourse" value="${esc(s.course)}"></label><label>Year<input id="sYear" type="number" value="${s.year}"></label></div><label>Day<select id="sDay">${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map(d=>`<option ${d===s.day?'selected':''}>${d}</option>`).join('')}</select></label><div class="two"><label>Start<input id="sStart" type="time" value="${s.start_time}" required></label><label>End<input id="sEnd" type="time" value="${s.end_time}" required></label></div><label>Subject<input id="sSub" value="${esc(s.subject)}" required></label><div class="two"><label>Room<input id="sRoom" value="${esc(s.room||'')}"></label><label>Teacher<input id="sTeacher" value="${esc(s.teacher||'')}"></label></div><button class="primary full">Save changes</button></form>`);$('#editSlotForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/timetable/'+id,{method:'PATCH',body:JSON.stringify({course:$('#sCourse').value,year:+$('#sYear').value,day:$('#sDay').value,start_time:$('#sStart').value,end_time:$('#sEnd').value,subject:$('#sSub').value,room:$('#sRoom').value,teacher:$('#sTeacher').value})});closeModal();toast('Timetable updated','ok');timetable()}catch(err){toast(err.message,'err')}}};
function teacherControls(type){if(!(me.role==='admin'||(me.role==='teacher'&&me.teacher_verified)))return '';return `<div class="card"><h3 style="margin-top:0">Faculty tools</h3><p class="muted">Update your course schedule from here.</p><button class="primary" data-action="openAddSlot">＋ Add timetable slot</button></div>`}
window.openAddSlot=()=>{modal(`<div class="modal-head"><h3>Add timetable slot</h3><button class="close" data-action="closeModal">×</button></div><form id="slotForm"><div class="two"><label>Course<input id="sCourse" value="BCA"></label><label>Year<input id="sYear" type="number" value="3"></label></div><label>Day<select id="sDay">${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map(d=>`<option>${d}</option>`).join('')}</select></label><div class="two"><label>Start<input id="sStart" type="time" required></label><label>End<input id="sEnd" type="time" required></label></div><label>Subject<input id="sSub" required></label><div class="two"><label>Room<input id="sRoom"></label><label>Teacher<input id="sTeacher" value="${esc(me.name)}"></label></div><button class="primary full">Save slot</button></form>`);const form=$('#slotForm');if(form)form.onsubmit=async e=>{e.preventDefault();try{await api('/api/timetable',{method:'POST',body:JSON.stringify({course:$('#sCourse').value,year:+$('#sYear').value,day:$('#sDay').value,start_time:$('#sStart').value,end_time:$('#sEnd').value,subject:$('#sSub').value,room:$('#sRoom').value,teacher:$('#sTeacher').value})});closeModal();toast('Timetable updated','ok');timetable()}catch(e){toast(e.message,'err')}}};

async function attendance(){const my=await api('/api/attendance/my');const faculty=me.role==='admin'||(me.role==='teacher'&&me.teacher_verified);let facultyPanel='';if(faculty)facultyPanel=`<div class="card"><div class="section-head" style="margin-top:0"><h3>${me.role==='admin'?'Attendance overview':'Teacher attendance'}</h3><button class="primary" data-action="openAttendanceSession">＋ Start session</button></div><p class="muted">Create and monitor short-lived attendance sessions. Students enter the generated code to mark themselves present.</p><div id="sessionList">Loading sessions…</div></div><div class="card"><div class="section-head" style="margin-top:0"><h3>Attendance report</h3><span>Student-wise percentage</span></div><div id="attendanceReport">Loading report…</div></div>`;const myPanel=me.role==='admin'?'':`<div class="card"><span class="badge green">MY ATTENDANCE</span><h3>Attendance history</h3><p class="muted">Your recorded sessions appear here.</p><div class="list">${my.length?my.map(a=>`<div class="list-item"><div class="avatar">✓</div><div class="grow"><b>${esc(a.subject)}</b><small>${a.session_date} · ${a.start_time}</small></div><span class="badge ${a.status==='present'?'green':'red'}">${a.status}</span></div>`).join(''):'<div class="empty">No attendance records yet.</div>'}</div></div>`;const checkIn=me.role==='student'?`<div class="card"><span class="badge">STUDENT CHECK-IN</span><h3>Enter attendance code</h3><p class="muted">Ask your teacher for the 6-digit session code.</p><div class="search-row"><input id="attCode" inputmode="numeric" maxlength="6" placeholder="123456"><button class="primary" data-action="markAttendance">Mark present</button></div></div>`:'';$('#content').innerHTML=`<div class="grid grid2">${myPanel}<div class="grid">${checkIn}${facultyPanel}</div></div>`;if(faculty){loadSessions();loadAttendanceReport()}}
async function loadAttendanceReport(){try{const rows=await api('/api/attendance/report');if($('#attendanceReport'))$('#attendanceReport').innerHTML=rows.length?`<div class="list">${rows.map(r=>`<div class="list-item"><div class="avatar">${initials(r.name)}</div><div class="grow"><b>${esc(r.name)}</b><small>${esc(r.course)} · Year ${r.year} · ${r.present_sessions}/${r.total_sessions} present</small></div><span class="badge ${r.percentage<75?'orange':'green'}">${r.percentage}%</span></div>`).join('')}</div>`:'<div class="empty">No attendance data yet.</div>'}catch(e){if($('#attendanceReport'))$('#attendanceReport').innerHTML=`<div class="notice">${esc(e.message)}</div>`}}
window.markAttendance=async()=>{try{const d=await api('/api/attendance/mark',{method:'POST',body:JSON.stringify({code:$('#attCode').value})});toast(d.message,'ok');attendance()}catch(e){toast(e.message,'err')}};
async function loadSessions(){const ss=await api('/api/attendance/sessions');if($('#sessionList'))$('#sessionList').innerHTML=ss.length?`<div class="list">${ss.slice(0,8).map(s=>`<div class="list-item"><div class="avatar">✓</div><div class="grow"><b>${esc(s.subject)}</b><small>${s.session_date} · ${s.start_time} · ${esc(s.group_name||'Open')}</small></div><span class="code">${s.code}</span><span class="badge green">${s.present_count}/${s.member_count||'—'}</span></div>`).join('')}</div>`:'<p class="muted">No sessions yet.</p>'}
window.openAttendanceSession=()=>{modal(`<div class="modal-head"><h3>Start attendance session</h3><button class="close" data-action="closeModal">×</button></div><form id="attForm"><label>Group ID (optional)<input id="aGroup" type="number" placeholder="e.g. 1"></label><label>Subject<input id="aSub" required placeholder="Data Structures"></label><div class="two"><label>Date<input id="aDate" type="date" required value="${new Date().toISOString().slice(0,10)}"></label><label>Start time<input id="aTime" type="time" required></label></div><label>Code validity (minutes)<input id="aMin" type="number" min="1" max="60" value="15"></label><button class="primary full">Generate attendance code</button></form>`);const form=$('#attForm');if(form)form.onsubmit=async e=>{e.preventDefault();try{const s=await api('/api/attendance/sessions',{method:'POST',body:JSON.stringify({group_id:$('#aGroup').value||null,subject:$('#aSub').value,session_date:$('#aDate').value,start_time:$('#aTime').value,expires_minutes:+$('#aMin').value})});closeModal();modal(`<div class="modal-head"><h3>Attendance code</h3><button class="close" data-action="closeModal">×</button></div><div style="text-align:center;padding:25px"><div style="font:700 46px/1 'Space Grotesk';letter-spacing:7px;color:var(--accent)">${s.code}</div><p class="muted">Share this code with the class. It expires automatically.</p><button class="primary" data-action="copyCode" data-args='["${s.code}"]'>Copy code</button></div>`);loadSessions()}catch(err){toast(err.message,'err')}}};

window.openGroup=async id=>{
 try{
  const groupId=Number(id);
  if(!Number.isInteger(groupId)||groupId<1)throw new Error('Invalid group');
  modal('<div class="modal-head"><h3>Opening group…</h3><button class="close" data-action="closeModal">×</button></div><div class="empty">Loading group details…</div>');
  const groupsList=cache.groups?.length?cache.groups:await api('/api/groups');
  const g=groupsList.find(x=>Number(x.id)===groupId);
  if(!g)throw new Error('Group not found');
  const members=await api('/api/groups/'+groupId+'/members');
  const canManage=me.role==='admin'||(me.role==='teacher'&&me.teacher_verified&&g.admin_id===me.id);
  modal(`<div class="modal-head"><div><h3>${esc(g.name)}</h3><span class="code">${esc(g.code)}</span></div><button class="close" data-action="closeModal">×</button></div><p class="muted">${esc(g.description||'College group')}</p><div class="notice">${g.members} members · ${esc(g.course)} · Year ${g.year}</div><div class="section-head"><h3>Members</h3><span>${members.length}</span></div><div class="list">${members.map(m=>`<div class="list-item"><div class="avatar">${initials(m.name)}</div><div class="grow"><b>${esc(m.name)}</b><small>${esc(m.role)} · ${esc(m.email)}</small></div>${canManage&&m.id!==me.id?`<button class="ghost" data-action="removeMember" data-args='[${id},${m.id}]'>Remove</button>`:''}</div>`).join('')}</div>${canManage?`<div class="section-head"><h3>Mass communication</h3><span>Gmail</span></div><div class="notice">Emails are sent using the configured Gmail account, with <b>${esc(me.name)}</b> as the display name.</div><form id="massEmailForm"><label>Subject<input id="mailSubject" required placeholder="Important class update"></label><label>Message<textarea id="mailBody" required placeholder="Write your message to everyone…"></textarea></label><button class="primary full">Send to everyone by Gmail</button></form>`:''}`);
  if(canManage) $('#massEmailForm').onsubmit=async e=>{e.preventDefault();try{const d=await api('/api/groups/'+groupId+'/email',{method:'POST',body:JSON.stringify({subject:$('#mailSubject').value,body:$('#mailBody').value})});toast(`Email sent to ${d.sent_count} members`,'ok');closeModal()}catch(err){toast(err.message,'err')}};
 }catch(e){modal(`<div class="modal-head"><h3>Unable to open group</h3><button class="close" data-action="closeModal">×</button></div><div class="notice">${esc(e.message||'Could not load group details')}</div>`)}
};
window.removeMember=async(gid,uid)=>{if(!confirm('Remove this member from the group?'))return;try{await api('/api/groups/'+gid+'/members/'+uid,{method:'DELETE'});toast('Member removed','ok');openGroup(gid)}catch(e){toast(e.message,'err')}};

async function events(){const es=await api('/api/events');$('#content').innerHTML=`<div class="card hero"><span class="badge" style="background:#ffffff1a;color:#fff">CAMPUS CALENDAR</span><h1>What’s happening next?</h1><p>Programs, workshops, seminars, competitions and college activities, all in one place.</p>${me.role==='admin'||(me.role==='teacher'&&me.teacher_verified)?'<button class="ghost" style="background:#fff;color:#5138d6" data-action="openEvent">＋ Publish event</button>':''}</div><div class="section-head"><h3>Upcoming events</h3><span>${es.length} events</span></div><div class="grid grid3">${es.map(e=>`<div class="card event-card"><div><span class="badge">${esc(e.category)}</span><h3>${esc(e.title)}</h3><p class="muted">${esc(e.description)}</p></div><div class="bottom"><div><b>📅 ${e.date}</b><small class="muted" style="display:block">${esc(e.time)} · ${esc(e.venue)}</small><small class="muted" style="display:block;margin-top:5px">👥 ${e.rsvp_count||0} going</small></div><div style="display:flex;gap:7px;align-items:center"><button class="${e.rsvp_status==='going'?'primary':'ghost'}" data-action="rsvpEvent" data-args='[${e.id},"${e.rsvp_status==="going"?"not_going":"going"}"]'>${e.rsvp_status==='going'?'Going':'I’m going'}</button><button class="ghost" data-action="openEventDetails" data-id="${e.id}">Details</button></div></div></div>`).join('')||'<div class="empty">No events yet.</div>'}</div>`}
window.rsvpEvent=async(id,status)=>{try{await api('/api/events/'+id+'/rsvp',{method:'POST',body:JSON.stringify({status})});toast(status==='going'?'Added to your events':'RSVP removed','ok');events()}catch(e){toast(e.message,'err')}};
window.openEventDetails=async id=>{try{const es=await api('/api/events');const e=es.find(x=>x.id===id);if(!e)return;modal(`<div class="modal-head"><div><h3>${esc(e.title)}</h3><span class="badge">${esc(e.category)}</span></div><button class="close" data-action="closeModal">×</button></div><p>${esc(e.description)}</p><div class="notice"><b>📅 ${esc(e.date)}</b><br>⏰ ${esc(e.time||'Time TBA')}<br>📍 ${esc(e.venue||'Venue TBA')}<br>👤 Published by ${esc(e.created_by_name||'CAMPus')}</div>`)}catch(err){toast(err.message,'err')}};
window.openEvent=()=>{modal(`<div class="modal-head"><h3>Publish event</h3><button class="close" data-action="closeModal">×</button></div><form id="eventForm"><label>Title<input id="eTitle" required></label><label>Category<select id="eCat"><option>Program</option><option>Workshop</option><option>Seminar</option><option>Competition</option><option>Other</option></select></label><label>Description<textarea id="eDesc" required></textarea></label><div class="two"><label>Date<input id="eDate" type="date" required></label><label>Time<input id="eTime" type="time"></label></div><label>Venue<input id="eVenue"></label><button class="primary full">Publish event</button></form>`);const form=$('#eventForm');if(form)form.onsubmit=async e=>{e.preventDefault();try{await api('/api/events',{method:'POST',body:JSON.stringify({title:$('#eTitle').value,category:$('#eCat').value,description:$('#eDesc').value,date:$('#eDate').value,time:$('#eTime').value,venue:$('#eVenue').value})});closeModal();toast('Event published','ok');events()}catch(err){toast(err.message,'err')}}};

async function notifications(){const ns=await api('/api/notifications');$('#content').innerHTML=`<div class="card"><div class="section-head" style="margin-top:0"><h3>Notifications</h3><div style="display:flex;gap:8px;align-items:center"><span>${ns.filter(n=>!n.read_at).length} unread</span>${ns.some(n=>!n.read_at)?'<button class="ghost" data-action="readAllNotifications">Mark all read</button>':''}</div></div><div class="list">${ns.length?ns.map(n=>{const match=n.type==='connection_request'&&n.body.match(/\[request:(\d+)\]/);const body=n.body.replace(/\s*\[request:\d+\]\s*$/,'');return `<div class="notif ${!n.read_at?'unread':''}" data-action="readNotif" data-id="${n.id}"><div style="font-size:22px">${n.type==='timetable_reminder'?'⏰':n.type==='teacher_verified'?'✓':n.type==='connection_request'?'🤝':'♢'}</div><div><b>${esc(n.title)}</b><div style="font-size:13px;margin-top:4px">${esc(body)}</div>${match?`<div style="display:flex;gap:8px;margin-top:9px"><button class="primary" data-action="acceptConnection" data-id="${match[1]}">Accept</button><button class="ghost" data-action="rejectConnection" data-id="${match[1]}">Decline</button></div>`:''}<small>${fmt(n.created_at)}</small></div></div>`}).join(''):'<div class="empty">You’re all caught up.</div>'}</div></div>`}
window.readNotif=async id=>{try{await api('/api/notifications/'+id+'/read',{method:'POST'});notifications();loadBadges()}catch{}};
window.readAllNotifications=async()=>{try{await api('/api/notifications/read-all',{method:'POST'});toast('All notifications marked read','ok');notifications();loadBadges()}catch(e){toast(e.message,'err')}};
window.acceptConnection=async id=>{try{await api('/api/connections/'+id+'/accept',{method:'POST'});toast('Connection accepted','ok');notifications();loadBadges()}catch(e){toast(e.message,'err')}};
window.rejectConnection=async id=>{try{await api('/api/connections/'+id+'/reject',{method:'POST'});toast('Connection request declined','ok');notifications();loadBadges()}catch(e){toast(e.message,'err')}};

async function profile(){const [u,allPosts,blockedUsers]=await Promise.all([api('/api/me'),api('/api/posts'),api('/api/users/blocked')]);const myPosts=allPosts.filter(p=>p.user_id===u.id);me=u;applyRoleUI();syncProfileUI();$('#content').innerHTML=`<div class="card" style="padding:0;overflow:hidden"><div class="profile-cover"></div><div style="padding:0 25px 25px"><div class="profile-main">${avatarMarkup(u)}<div><h2 style="margin:0;font-family:'Space Grotesk'">${esc(u.name)}</h2><span class="badge">${esc(u.role)}${u.role==='teacher'?(u.teacher_verified?' · verified':' · pending verification'):''}</span></div></div><p class="muted">${esc(u.bio||'Add a short bio to tell people about you.')}</p><div class="grid grid3"><div class="kpi"><small class="muted">Course</small><strong>${esc(u.course||'—')}</strong></div><div class="kpi"><small class="muted">Year</small><strong>${u.year||'—'}</strong></div><div class="kpi"><small class="muted">Account</small><strong style="text-transform:capitalize">${esc(u.role)}</strong></div></div><div class="section-head"><h3>Profile settings</h3></div><form id="profileForm"><label>Profile photo<input id="pAvatar" type="file" accept="image/jpeg,image/png,image/webp"></label><div class="two"><label>Name<input id="pName" value="${esc(u.name)}" required></label><label>Course<input id="pCourse" value="${esc(u.course||'')}"></label></div><label>Bio<textarea id="pBio">${esc(u.bio||'')}</textarea></label><button class="primary">Save profile</button></form><div class="notice" style="margin-top:15px">${u.role==='personal'?'Personal accounts are intentionally limited to normal one-to-one communication.':u.role==='teacher'&&!u.teacher_verified?'Your teacher account is pending admin verification. Faculty controls unlock after approval.':'Your CAMPus account is active and ready.'}</div></div></div>${blockedUsers.length?`<div class="section-head"><h3>Blocked users</h3><span>${blockedUsers.length} blocked</span></div><div class="grid grid3">${blockedUsers.map(u=>`<div class="card"><div class="post-head">${avatarMarkup(u,'sm')}<div class="grow"><b>${esc(u.name)}</b><small>${esc(u.role)}</small></div><button class="ghost" data-action="unblockUser" data-id="${u.id}">Unblock</button></div></div>`).join('')}</div>`:''}<div class="section-head"><h3>My posts</h3><span>${myPosts.length} posts</span></div><div class="grid">${myPosts.length?myPosts.map(ownPostCard).join(''):'<div class="card empty">You have not shared any posts yet.</div>'}</div>`;const form=$('#profileForm');if(form)form.onsubmit=async e=>{e.preventDefault();try{const file=$('#pAvatar')?.files?.[0];if(file&&(file.size>1024*1024||!/^image\/(jpeg|png|webp)$/.test(file.type)))throw Error('Choose a JPG, PNG or WebP image smaller than 1 MB');let avatar_data='';if(file)avatar_data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Could not read photo'));r.readAsDataURL(file)});const updated=await api('/api/me',{method:'PATCH',body:JSON.stringify({name:$('#pName').value,course:$('#pCourse').value,bio:$('#pBio').value,avatar_data})});me=updated;syncProfileUI();toast('Profile updated','ok');profile()}catch(err){toast(err.message,'err')}}}

function teacherRows(ts){return ts.map(t=>`<tr><td><b>${esc(t.name)}</b></td><td>${esc(t.email)}</td><td>${esc(t.course)} · ${t.year}</td><td><span class="badge ${t.teacher_verified?'green':'orange'}">${t.teacher_verified?'Verified':'Pending'}</span></td><td><button class="ghost" data-action="reviewTeacher" data-id="${t.id}">Review</button> ${t.teacher_verified?`<button class="ghost" data-action="verifyTeacher" data-args='[${t.id},false]'>Revoke</button>`:`<button class="primary" data-action="verifyTeacher" data-args='[${t.id},true]'>Verify</button>`}</td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">No matching teachers found.</div></td></tr>'}
async function admin(){if(me.role!=='admin'){nav('home');return}const [ts,logs,reports]=await Promise.all([api('/api/admin/teachers'),api('/api/admin/audit-logs'),api('/api/admin/post-reports')]);$('#content').innerHTML=`<div class="card hero"><span class="badge" style="background:#ffffff1a;color:#fff">ADMIN CONSOLE</span><h1>Keep CAMPus trusted.</h1><p>Review institution, department, employee ID, qualification, subjects and proof document before verification.</p></div><div class="section-head"><h3>Teacher verification</h3><span>${ts.filter(t=>!t.teacher_verified).length} pending</span></div><div class="card admin-table-card"><div class="teacher-search"><input id="teacherSearch" placeholder="Search by name, email, institution or department…" oninput="filterTeachers()"><span class="badge">${ts.length} teachers</span></div><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Course</th><th>Status</th><th></th></tr></thead><tbody id="teacherRows">${teacherRows(ts)}</tbody></table></div><div class="section-head"><h3>Reported posts</h3><span>${reports.length} pending</span></div><div class="card admin-table-card"><table class="table"><thead><tr><th>Post owner</th><th>Reporter</th><th>Reason</th><th></th></tr></thead><tbody>${reports.length?reports.map(r=>`<tr><td>${esc(r.owner_name)}</td><td>${esc(r.reporter_name)}</td><td>${esc(r.reason)}</td><td><button class="ghost" data-action="resolveReport" data-id="${r.id}">Mark reviewed</button></td></tr>`).join(''):'<tr><td colspan="4"><div class="empty">No pending reports.</div></td></tr>'}</tbody></table></div><div class="section-head"><h3>Security audit log</h3><span>${logs.length} recent actions</span></div><div class="card admin-table-card"><table class="table"><thead><tr><th>Time</th><th>Action</th><th>User</th><th>Details</th></tr></thead><tbody>${logs.length?logs.map(l=>`<tr><td>${fmt(l.created_at)}</td><td>${esc(l.action)}</td><td>${esc(l.user_name||'System')}</td><td>${esc(l.details||'')}</td></tr>`).join(''):'<tr><td colspan="4"><div class="empty">No audit activity yet.</div></td></tr>'}</tbody></table></div>`;cache.adminTeachers=ts}
window.resolveReport=async id=>{try{await api('/api/admin/post-reports/'+id+'/resolve',{method:'POST'});toast('Report marked reviewed','ok');admin()}catch(e){toast(e.message,'err')}};
window.filterTeachers=()=>{const q=($('#teacherSearch')?.value||'').trim().toLowerCase();const ts=(cache.adminTeachers||[]).filter(t=>[t.name,t.email,t.institution,t.department,t.employee_id,t.qualification,t.teaching_subjects,t.teacher_verified?'verified':'pending'].some(v=>String(v||'').toLowerCase().includes(q)));if($('#teacherRows'))$('#teacherRows').innerHTML=teacherRows(ts)};
window.reviewTeacher=async id=>{try{const t=(await api('/api/admin/teachers')).find(x=>x.id===Number(id));if(!t)return toast('Teacher not found','err');modal(`<div class="modal-head"><h3>Review teacher details</h3><button class="ghost" data-action="closeModal">Close</button></div><div class="verification-review"><div><b>Name</b><span>${esc(t.name)}</span></div><div><b>Email</b><span>${esc(t.email)}</span></div><div><b>Institution</b><span>${esc(t.institution||'Not provided')}</span></div><div><b>Department</b><span>${esc(t.department||'Not provided')}</span></div><div><b>Employee ID</b><span>${esc(t.employee_id||'Not provided')}</span></div><div><b>Qualification</b><span>${esc(t.qualification||'Not provided')}</span></div><div><b>Teaching subjects</b><span>${esc(t.teaching_subjects||'Not provided')}</span></div><div><b>Proof document</b><span>${t.verification_document?`<a href="${esc(t.verification_document)}" target="_blank" rel="noopener">Open proof link</a>`:'Not provided'}</span></div></div>${t.teacher_verified?'<div class="notice">This teacher is already verified.</div>':`<button class="primary full" data-action="verifyTeacher" data-args='[${t.id},true]'>Verify after review</button>`}`)}catch(e){toast(e.message,'err')}};
window.verifyTeacher=async(id,on)=>{try{await api('/api/admin/teachers/'+id+'/'+(on?'verify':'revoke'),{method:'POST'});closeModal();toast(on?'Teacher verified':'Verification revoked','ok');admin()}catch(e){toast(e.message,'err')}};

function modal(html){window.closeModal();const w=document.createElement('div');w.id='modalWrap';w.className='modal-wrap';w.innerHTML=`<div class="modal">${html}</div>`;document.body.appendChild(w)}window.closeModal=()=>$('#modalWrap')?.remove();
async function loadBadges(){try{const ns=await api('/api/notifications'),cs=await api('/api/chats');const n=ns.filter(x=>!x.read_at).length,c=cs.reduce((a,x)=>a+(x.unread||0),0);$('#notifBadge').style.display=n?'block':'none';$('#topNotifDot').style.display=n?'block':'none';$('#chatBadge').style.display=c?'block':'none'}catch{}}

(async()=>{if(token){try{me=await api('/api/me');showApp()}catch{localStorage.removeItem('campus_token');token=null;showAuth()}}else{showAuth();if(new URLSearchParams(location.search).has('reset_token')){$$('.tab').forEach(x=>x.classList.remove('active'));showAuthForm('#resetForm')}}})();
